		lock, _ := json.Marshal([]string{opReopen, u.Tenant, u.User, key})
		if _, err = tx.Exec(ctx, `SELECT pg_advisory_xact_lock(hashtextextended($1,0))`, string(lock)); err != nil {
			return protocol.ItemResult{}, false, err
		}

		// The reason is part of the request identity, so the same key cannot
		// silently replay a response for a different reopen request.
		hash := ledger.Fingerprint(opReopen, []string{id, reason})
		var savedHash string
		var saved []byte
		err = tx.QueryRow(ctx, `SELECT "requestHash",response FROM "ActionRequest"
			WHERE "tenantId"=$1 AND "actorId"=$2 AND operation=$3 AND key=$4`,
			u.Tenant, u.User, opReopen, key).Scan(&savedHash, &saved)
		switch {
		case err == nil && savedHash != hash:
			return protocol.ItemResult{}, false, &protocol.Rejection{Status: 409}
		case err == nil:
			var result protocol.ItemResult
			if err = json.Unmarshal(saved, &result); err != nil {
				return protocol.ItemResult{}, false, err
			}
			if err = tx.Commit(ctx); err != nil {
				return protocol.ItemResult{}, false, err
			}
			return result, true, nil
		case !errors.Is(err, pgx.ErrNoRows):
			return protocol.ItemResult{}, false, err
		}

		var foundID string
		err = tx.QueryRow(ctx, `SELECT id FROM "Purchase"
			WHERE id=$1 AND "tenantId"=$2 AND "createdBy"=$3 AND status='rejected'
			FOR UPDATE`, id, u.Tenant, u.User).Scan(&foundID)
		if errors.Is(err, pgx.ErrNoRows) {
			return protocol.ItemResult{}, false, &protocol.Rejection{Status: 409}
		}
		if err != nil {
			return protocol.ItemResult{}, false, err
		}

		if _, err = tx.Exec(ctx, `UPDATE "Purchase" SET status='submitted'
			WHERE id=$1 AND "tenantId"=$2 AND "createdBy"=$3 AND status='rejected'`,
			id, u.Tenant, u.User); err != nil {
			return protocol.ItemResult{}, false, err
		}

		result := protocol.ItemResult{ID: foundID, Status: "submitted"}
		response, err := json.Marshal(result)
		if err != nil {
			return protocol.ItemResult{}, false, err
		}
		if _, err = tx.Exec(ctx, `INSERT INTO "ActionRequest" ("tenantId","actorId",operation,key,"requestHash",response)
			VALUES ($1,$2,$3,$4,$5,$6::jsonb)`, u.Tenant, u.User, opReopen, key, hash, string(response)); err != nil {
			return protocol.ItemResult{}, false, err
		}
		if _, err = tx.Exec(ctx, `INSERT INTO "ApprovalAudit" ("tenantId","purchaseId","approvedBy",operation,"idempotencyKey","fromStatus","toStatus",reason)
			VALUES ($1,$2,$3,$4,$5,'rejected','submitted',$6)`, u.Tenant, id, u.User, opReopen, key, reason); err != nil {
			return protocol.ItemResult{}, false, err
		}
		if _, err = tx.Exec(ctx, `INSERT INTO "PurchaseEvent" ("tenantId","purchaseId",type,"actorId","idempotencyKey")
			VALUES ($1,$2,'purchase.reopened',$3,$4)`, u.Tenant, id, u.User, key); err != nil {
			return protocol.ItemResult{}, false, err
		}
		if err = tx.Commit(ctx); err != nil {
			return protocol.ItemResult{}, false, err
		}
		return result, false, nil
	}
}
